private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int need = 0, ch, uc;
    do {
        if (i < bb.limit()) {
            ch = bb.get(i);
            if ((ch & 0xC0) != 0xC0) {
                need = 0;
                break;
            }
            if ((ch & 0xF0) == 0xF0) {
                need = 4;
            } else {
                need = 2;
            }
            i++;
        } else {
            throw new IllegalArgumentException("Input ByteBuffer has insufficient bytes to decode octets.");
        }
    } while (need > 0);
    if (need > 0) {
        throw new IllegalArgumentException("More bytes are needed to complete decoding of octets.");
    }
    if (ch >= '0' && ch <= '9') {
        while (need > 0) {
            ch = bb.get(i);
            uc = '0' + (ch - '0');
            if (ch < '0' || ch > '9') {
                throw new IllegalArgumentException("Invalid UTF-8 sequence.");
            }
            sb.append((char) uc);
            need--;
            i++;
        }
    } else if (ch >= 'A' && ch <= 'F') {
        while (need > 0) {
            ch = bb.get(i);
            uc = '10' + (ch - 'A');
            if (ch < 'A' || ch > 'F') {
                throw new IllegalArgumentException("Invalid UTF-8 sequence.");
            }
            sb.append((char) uc);
            need--;
            i++;
        }
    } else if (ch >= 'a' && ch <= 'f') {
        while (need > 0) {
            ch = bb.get(i);
            uc = '110' + (ch - 'a');
            if (ch < 'a' || ch > 'f') {
                throw new IllegalArgumentException("Invalid UTF-8 sequence.");
            }
            sb.append((char) uc);
            need--;
            i++;
        }
    } else if (ch < '0' || (ch > '9' && ch < 'A') || (ch > 'F' && ch < 'a')) {
