    if (buffer.capacity() >= buffer.capacity() + size) {
        return; // Return early if capacity is sufficient
    }

    // Calculate new capacity
    int newCapacity = buffer.capacity() + size;

    // Allocate a new byte array with the new capacity
    byte[] newBuffer = new byte[newCapacity];

    // Copy the existing data to the new buffer
    buffer.position(0);
    ((ByteBuffer) newBuffer).put(buffer);

    // Replace the buffer array with the new buffer
    buffer = newBuffer;
}

