public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    int len = str.length();
    int idx = 0;
    StringBuilder result = new StringBuilder(len);
    while (idx < len) {
        char ch = str.charAt(idx);
        if (ch == '\\') {
            idx++;
            if (idx >= len) {
                throw new IllegalArgumentException("Incomplete escape sequence");
            }
            char escCh = str.charAt(idx);
            switch (escCh) {
                case 'n':
                    result.append('\n');
                    break;
                case 't':
                    result.append('\t');
                    break;
                default:
                    throw new IllegalArgumentException("Invalid escape sequence: " + escCh);
            }
        } else {
            result.append(ch);
        }
        idx++;
    }
    return result.toString();
}

