private static <V,E> boolean isClique(Graph<V,E> graph,Set<V> vertices){
    if (graph == null || vertices == null || vertices.isEmpty()){
        throw new IllegalArgumentException("Graph and vertices cannot be null or empty");
    }

    int numVertices = vertices.size();
    if (numVertices <= 1){
        return true;
    }

    // Check each vertex in the set
    for (V vertex : vertices){
        Set<E> neighbors = graph.neighbors(vertex);

        // Check if any neighboring vertex is not in the graph or not in the set
        if (neighbors == null || !neighbors.containsAll(vertices)){
            return false;
        }
    }

    return true;
}

